@startuml

class Employee {
  + name : string
  + department : string
  + staffNumber : int
}

class IdentityCard {
  + cardNumber : int
}

class GuestCard {
  + cardNumber : int
  + currentDate : date
}

class Car {
  + licensePlate : string
}

class CardReader {
  + verify(card: IdentityCard) : boolean
}

class Barrier {
  + raise() : void
}

class CarPark {
  + isFull() : boolean
}

class Sign {
  + displayStatus(status: string) : void
}

class Reception {
  + collect(card: GuestCard) : void
}

Employee "1" -- "1" IdentityCard : wears
IdentityCard "1" -- "0..1" Car : used by
GuestCard "0..*" -- "0..1" Car : used by
Car "1" -- "1" Barrier : triggers
CarPark "1" -- "1" Barrier : has
CarPark "1" -- "1" Sign : has
CarPark "1" -- "1" CarPark : manages
Reception "1" -- "*" GuestCard : manages

@enduml

